    if len(c_raw) != 24:
        raise ValueError('Transportation cost matrix must have 24 rows (suppliers)')
    for row in c_raw:
        if len(row) != 25:
            raise ValueError('Each row of transportation cost matrix must have 25 columns (supermarkets)')
    if set(f.keys()) != set(suppliers):
        raise ValueError('Fixed cost keys do not match supplier set')
    if set(d.keys()) != set(supermarkets):
        raise ValueError('Demand keys do not match supermarket set')
    c = {}
    for i_idx, i in enumerate(suppliers):
        c[i] = {}
        for j_idx, j in enumerate(supermarkets):
            c[i][j] = c_raw[i_idx][j_idx]
    m = gp.Model('facility_location')
    m.Params.MIPGap = 0.0001
    y = m.addVars(suppliers, vtype=GRB.BINARY, lb=0, ub=1, name='')
    x = m.addVars(suppliers, supermarkets, vtype=GRB.CONTINUOUS, lb=0, name='')
    m.setObjective(gp.quicksum((f[i] * y[i] for i in suppliers)) + gp.quicksum((c[i][j] * x[i, j] for i in suppliers for j in supermarkets)), GRB.MINIMIZE)
    for j in supermarkets:
        m.addConstr(gp.quicksum((x[i, j] for i in suppliers)) == d[j], name='demand_%s' % j)
    for i in suppliers:
        for j in supermarkets:
            m.addConstr(x[i, j] <= d[j] * y[i], name='link_%s_%s' % (i, j))
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print('ObjVal', m.ObjVal)
        for v in m.getVars():
            print(v.VarName, v.X)
    else:
        print('Solver status:', m.Status)
    return m
